begin;
create function pg_temp.check(b boolean,label text) returns text language plpgsql as $$ begin if b is distinct from true then raise exception 'S1_M7_UPGRADE_ASSERTION: %',label; end if; return 'ok - '||label; end; $$;
select pg_temp.check((select count(*)=4 from public.consent_documents where is_current) and (select count(*)=1 from public.terms_versions where is_current),'M7 upgrade publishes all documents and a single bundle');
select pg_temp.check((select jsonb_agg(to_jsonb(e) order by id) from public.profile_consents e)=(select events from pg_temp.m7_upgrade_before),'M7 upgrade preserves every existing event without backfill');
select pg_temp.check((select to_jsonb(t)-'is_current' from public.terms_versions t where version='2026-08-17')=(select old_bundle from pg_temp.m7_upgrade_before),'M7 retains old bundle content and timing');
select pg_temp.check((select jsonb_agg(to_jsonb(s) order by profile_id,kind) from public.profile_consent_states s where kind='marketing')=(select marketing from pg_temp.m7_upgrade_before),'M7 does not reset already migrated marketing states or two-year dates');
select pg_temp.check(not exists(select 1 from public.profile_consent_states where kind='health') and not exists(select 1 from public.profile_health_preferences),'M7 upgrade never infers health approval from legacy metadata');
create function pg_temp.state_of(command text) returns text language plpgsql as $$ begin execute command; return '00000'; exception when others then return sqlstate; end; $$;
grant execute on function pg_temp.check(boolean,text),pg_temp.state_of(text) to authenticated;
grant select on pg_temp.m7_upgrade_before to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000001-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.check(public.get_my_consent_status()->'required'->>'status'='required','upgraded legacy user must explicitly accept the activated bundle');
select pg_temp.check(pg_temp.state_of('select public.get_my_food_preferences()')='S1001','upgraded legacy JWT stays blocked before reconsent');
select public.record_required_consents(gen_random_uuid(),public.get_consent_manifest()->>'bundle_version',(select jsonb_object_agg(k,jsonb_build_object('version',v->>'version','content_hash',v->>'content_hash')) from jsonb_each(public.get_consent_manifest()->'documents') e(k,v) where k in ('service','privacy')),'{"service":true,"privacy":true}');
select pg_temp.check(public.get_my_consent_status()->'required'->>'status'='accepted','upgraded legacy JWT passes after explicit current reconsent');
select pg_temp.check(public.get_my_food_preferences()='{"schema_version":1,"preferences":{},"revision":"0"}'::jsonb,'upgraded user reads empty revision zero without restored taste answers');
select pg_temp.check(not exists(select 1 from public.profile_food_preferences),'reading empty upgraded food preferences creates no row');
select pg_temp.check(pg_temp.state_of($q$select public.save_my_food_preferences('{}',1)$q$)='S1004','stale first food save is refused');
select pg_temp.check(pg_temp.state_of($q$select public.save_my_food_preferences('{"meat":"yes"}',0)$q$)='22023','invalid first food save is refused');
select pg_temp.check(not exists(select 1 from public.profile_food_preferences),'rejected first saves create no food row');
select pg_temp.check(public.save_my_food_preferences('{"korean":false,"meat":true,"seafood":true,"western":false,"chinese":true,"japanese":false}',0)=jsonb_build_object('schema_version',1,'preferences','{"korean":false,"meat":true,"seafood":true,"western":false,"chinese":true,"japanese":false}'::jsonb,'revision','1'),'explicit saveTastes six-boolean payload creates revision one');
select pg_temp.check(public.get_my_food_preferences()->'preferences'='{"korean":false,"meat":true,"seafood":true,"western":false,"chinese":true,"japanese":false}'::jsonb,'new six-key answers roundtrip without legacy values');
select pg_temp.check((select count(*)=1 and bool_and(profile_id=auth.uid()) from public.profile_food_preferences),'first food save is owned only by the current JWT');
reset role;
select pg_temp.check((select jsonb_agg(to_jsonb(s) order by profile_id,kind) from public.profile_consent_states s where kind='marketing')=(select marketing from pg_temp.m7_upgrade_before),'required reconsent preserves old marketing grant and decline');
select pg_temp.check((select count(*)=7 from public.profile_consents where source='legacy') and (select count(*)=2 from public.profile_consents where source='reconsent'),'only two explicit reconsent events are new after M7 upgrade');
rollback;
